const hectorArchives = {"orders": {"label": "Order proofs", "total": 318, "note": "A few moments from order handoff to customer confirmation.", "images": [{"category": "orders", "title": "Nitro delivery & customer confirmation", "src": "data:image/jpeg;base64,"}, {"category": "orders", "title": "Order handoff & confirmation", "src": "data:image/jpeg;base64,"}, {"category": "orders", "title": "Completed order conversation", "src": "data:image/jpeg;base64,"}]}, "vouches": {"label": "Customer vouches", "total": 318, "note": "A few customer confirmations, in their own words.", "images": [{"category": "vouches", "title": "Customer chat vouch", "src": "data:image/jpeg;base64,"}, {"category": "orders", "title": "Customer delivery confirmation", "src": "data:image/jpeg;base64,"}, {"category": "orders", "title": "Order handoff & confirmation", "src": "data:image/jpeg;base64,"}]}, "reviews": {"label": "Customer reviews", "total": 58, "note": "A selection of feedback and ratings from the review channel.", "images": [{"category": "vouches", "title": "Community reviews \u00b7 01", "src": "data:image/jpeg;base64,"}, {"category": "vouches", "title": "Community reviews \u00b7 02", "src": "data:image/jpeg;base64,"}, {"category": "vouches", "title": "Community reviews \u00b7 04", "src": "data:image/jpeg;base64,"}]}};
(() => {
const screen = document.getElementById('hf-screen');
const image = document.getElementById('hf-image');
const caption = document.getElementById('hf-caption');
const thumbs = document.getElementById('hf-thumbs');
let active = 'vouches', current = 0;
function display(index) {
 const collection = hectorArchives[active]; current = (index + collection.images.length) % collection.images.length;
 image.src = collection.images[current].src; image.alt = collection.images[current].title;
 caption.textContent = `EXAMPLE ${String(current+1).padStart(2,'0')} / 03 · ${collection.images[current].title}`;
 [...thumbs.children].forEach((button,i) => button.setAttribute('aria-pressed',String(i===current)));
}
function select(key) {
 active = key; const collection = hectorArchives[key];
 document.getElementById('hf-screen-title').textContent = collection.label;
 document.getElementById('hf-count').textContent = collection.total;
 document.getElementById('hf-description').textContent = collection.note;
 document.querySelectorAll('[data-hf-switch]').forEach(button => button.setAttribute('aria-pressed',String(button.dataset.hfSwitch===key)));
 thumbs.replaceChildren();
 collection.images.forEach((item,i) => {
  const button = document.createElement('button');button.type='button';button.setAttribute('aria-label',`Show example ${i+1}: ${item.title}`);
  const img = document.createElement('img');img.src=item.src;img.alt='';
  const number = document.createElement('span');number.textContent=String(i+1).padStart(2,'0');button.append(img,number);
  button.addEventListener('click',()=>display(i));thumbs.append(button);
 });display(0);
}
document.querySelectorAll('[data-hf-open]').forEach(button=>button.addEventListener('click',()=>{select(button.dataset.hfOpen);screen.showModal();screen.scrollTop=0;}));
document.querySelectorAll('[data-hf-switch]').forEach(button=>button.addEventListener('click',()=>select(button.dataset.hfSwitch)));
document.getElementById('hf-close').addEventListener('click',()=>screen.close());
document.getElementById('hf-prev').addEventListener('click',()=>display(current-1));
document.getElementById('hf-next').addEventListener('click',()=>display(current+1));
screen.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'){event.preventDefault();display(current-1);}if(event.key==='ArrowRight'){event.preventDefault();display(current+1);}});
screen.addEventListener('close',()=>{image.removeAttribute('src');thumbs.replaceChildren();});
})();
